function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // two characters
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 - 20);
  ctx.lineTo(W/4, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 - 20, H/2);
  ctx.lineTo(W/4 + 20, H/2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 - 20);
  ctx.lineTo(W - W/4, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 - 20, H/2);
  ctx.lineTo(W - W/4 + 20, H/2);
  ctx.stroke();

  // connection line
  ctx.beginPath();
  ctx.moveTo(W/4 + 20, H/2);
  ctx.lineTo(W - W/4 - 20, H/2);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  // dynamic connection
  ctx.beginPath();
  ctx.moveTo(W/4 + 20 + Math.sin(t) * 10, H/2 + Math.cos(t) * 10);
  ctx.lineTo(W - W/4 - 20 + Math.sin(t + Math.PI) * 10, H/2 + Math.cos(t + Math.PI) * 10);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.restore();
}
